1	package registry
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	// Registry 是一个已打开的本地登记册。同一目录同时只能被一个 Registry
15	// 独占打开（目录内 flock）；单个 Registry 的方法可被多个 goroutine
16	// 并发调用，所有状态变更与落盘在同一把互斥锁内一次完成。
17	type Registry struct {
18		dir    string
19		store  *store
20		state  *snapshot
21		mu     sync.Mutex
22		closed bool
23		// now 返回当前时间，到期判断以此为准；生产环境为 time.Now，测试可替换。
24		now func() time.Time
25	}
26	
27	// Create 在 dir 新建并打开一个空登记册。调用者通过 dir 指定本机数据
28	// 位置；目录不存在会被创建。目录中已存在登记册数据时返回错误，
29	// 已有的数据不会被覆盖。
30	func Create(dir string) (*Registry, error) {
31		if strings.TrimSpace(dir) == "" {
32			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
33		}
34		if err := os.MkdirAll(dir, dirMode); err != nil {
35			return nil, fmt.Errorf("registry: 无法创建数据目录: %w", err)
36		}
37		if _, err := os.Stat(dataFile(dir)); err == nil {
38			return nil, fmt.Errorf("%w: %s 已存在登记册数据，应用 Open 打开", ErrAlreadyExists, dir)
39		} else if !errors.Is(err, os.ErrNotExist) {
40			return nil, fmt.Errorf("registry: 无法访问数据目录: %w", err)
41		}
42		lock, err := acquireLock(dir)
43		if err != nil {
44			return nil, err
45		}
46		// 取锁后再确认一次，避免与另一个进程的 Create 竞争。
47		if _, err := os.Stat(dataFile(dir)); err == nil {
48			_ = releaseLock(lock)
49			return nil, fmt.Errorf("%w: %s 已存在登记册数据", ErrAlreadyExists, dir)
50		}
51		st := &store{dir: dir, lock: lock}
52		s := newSnapshot()
53		if err := st.save(s); err != nil {
54			_ = releaseLock(lock)
55			return nil, err
56		}
57		return &Registry{dir: dir, store: st, state: s, now: time.Now}, nil
58	}
59	
60	// Open 打开 dir 中的已有登记册。数据文件缺失视为空目录的新建场景，
61	// 应使用 Create；数据存在但无法读取或解析时返回包裹 ErrCorrupt 的
62	// 错误，不会被静默当成空登记册。
63	func Open(dir string) (*Registry, error) {
64		if strings.TrimSpace(dir) == "" {
65			return nil, fmt.Errorf("%w: 数据目录不能为空", ErrInvalidArgument)
66		}
67		if info, err := os.Stat(dir); err != nil {
68			return nil, fmt.Errorf("registry: 无法打开数据目录: %w", err)
69		} else if !info.IsDir() {
70			return nil, fmt.Errorf("%w: %s 不是目录", ErrInvalidArgument, dir)
71		}
72		lock, err := acquireLock(dir)
73		if err != nil {
74			return nil, err
75		}
76		// 数据文件不存在不是"空登记册"：明确报错，提示用 Create 新建，
77		// 绝不把无数据目录静默当成空登记册。
78		if _, err := os.Stat(dataFile(dir)); err != nil {
79			_ = releaseLock(lock)
80			if errors.Is(err, os.ErrNotExist) {
81				return nil, fmt.Errorf("%w: %s 中没有登记册数据，请用 Create 新建", ErrNotFound, dir)
82			}
83			return nil, fmt.Errorf("registry: 无法访问登记册数据: %w", err)
84		}
85		s, err := load(dir)
86		if err != nil {
87			_ = releaseLock(lock)
88			return nil, err
89		}
90		return &Registry{dir: dir, store: &store{dir: dir, lock: lock}, state: s, now: time.Now}, nil
91	}
92	
93	// Close 正常关闭登记册并释放独占锁。关闭后不能再调用其他方法。
94	func (r *Registry) Close() error {
95		r.mu.Lock()
96		defer r.mu.Unlock()
97		if r.closed {
98			return nil
99		}
100		r.closed = true
101		return releaseLock(r.store.lock)
102	}
103	
104	func releaseLock(f *os.File) error {
105		err := f.Close() // Close 同时释放 flock
106		if err != nil {
107			return fmt.Errorf("registry: 关闭登记册失败: %w", err)
108		}
109		return nil
110	}
111	
112	func (r *Registry) checkOpen() error {
113		if r.closed {
114			return fmt.Errorf("registry: 登记册已关闭")
115		}
116		return nil
117	}
118	
119	// commit 将当前状态原子落盘；落盘失败时以磁盘内容为准重新加载，
120	// 避免内存状态与已持久化状态不一致。
121	func (r *Registry) commit() error {
122		if err := r.store.save(r.state); err != nil {
123			if s, lerr := load(r.dir); lerr == nil {
124				r.state = s
125			}
126			return err
127		}
128		return nil
129	}
130	
131	// ---- 账户 ----
132	
133	// RegisterAccount 以唯一编号登记账户，登记后即为可用状态。
134	func (r *Registry) RegisterAccount(id, metadata string) error {
135		r.mu.Lock()
136		defer r.mu.Unlock()
137		if err := r.checkOpen(); err != nil {
138			return err
139		}
140		if strings.TrimSpace(id) == "" {
141			return fmt.Errorf("%w: 账户编号不能为空", ErrInvalidArgument)
142		}
143		if _, ok := r.state.Accounts[id]; ok {
144			return fmt.Errorf("%w: 账户 %s", ErrAlreadyExists, id)
145		}
146		r.state.Accounts[id] = account{ID: id, Metadata: metadata, Active: true}
147		return r.commit()
148	}
149	
150	// DeactivateAccount 停用账户。停用后其原有藏品与历史仍可查询，但不能
151	// 再发行、发起或接收新的转让；停用不影响已经落盘的任何记录。
152	//
153	// 停用以保存成功为准：停用状态尚未原子替换原数据就发生写入错误（如数据
154	// 位置暂时无法写入）时，返回本次实际的保存错误，不返回成功，也不能用失败
155	// 后重新读取原数据时的错误取代它。即使原数据仍在、却暂时无法读取或解析、
156	// 状态未能按磁盘重建，同一个仍打开的登记册也必须保持停用前的样子：该账户
157	// 仍可用，编号与元数据不变，其已有藏品的持有人、版本与历史原样保留；其他
158	// 账户此前已经成功停用的状态不被恢复为可用。原数据仍可读取的普通保存失败
159	// 同样撤销本次变化，不依赖重新读取成功。随后另一次无关操作成功保存也不会
160	// 把这次未保存的停用夹带落盘。保存条件恢复后该账户仍按原有规则参与转让；
161	// 之后再次提交停用须重新完成保存，成功返回后才显示不可用，并按现有规则
162	// 拒绝其发起或接收新的转让。
163	func (r *Registry) DeactivateAccount(id string) error {
164		r.mu.Lock()
165		defer r.mu.Unlock()
166		if err := r.checkOpen(); err != nil {
167			return err
168		}
169		a, ok := r.state.Accounts[id]
170		if !ok {
171			return fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
172		}
173		if !a.Active {
174			return nil // 停用是幂等的终态，已停用直接成功，不要求再次写入
175		}
176		// 保存停用前的账户记录：停用以一次保存完成为准。commit 失败且磁盘
177		// 暂时不可读、状态未能按磁盘重建时据此显式撤销，否则这次未保存的停用
178		// 会留在当前已打开的登记册中（GetAccount 显示不可用、转让被按停用
179		// 拒绝），并被随后另一次成功保存夹带落盘。
180		prev := a
181		a.Active = false
182		r.state.Accounts[id] = a
183		if err := r.commit(); err != nil {
184			// commit 失败时已尝试按磁盘内容重建状态：重建成功则账户已随旧状态
185			// 整体恢复可用，写回的记录与磁盘一致；磁盘暂时不可读、状态未能重建
186			// 时本次停用仍在，显式恢复为停用前记录，藏品持有、版本与历史本就未
187			// 被触碰。返回实际写入错误，而非成功或重新读取时的错误。
188			r.state.Accounts[id] = prev
189			return err
190		}
191		return nil
192	}
193	
194	// GetAccount 查询账户；账户不存在时返回包裹 ErrNotFound 的错误。
195	func (r *Registry) GetAccount(id string) (Account, error) {
196		r.mu.Lock()
197		defer r.mu.Unlock()
198		if err := r.checkOpen(); err != nil {
199			return Account{}, err
200		}
201		a, ok := r.state.Accounts[id]
202		if !ok {
203			return Account{}, fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
204		}
205		return Account{ID: a.ID, Metadata: a.Metadata, Active: a.Active}, nil
206	}
207	
208	// ---- 系列 ----
209	
210	// CreateSeries 登记一个系列，记录创建账户与文字元数据。创建账户必须
211	// 已登记且可用；后续只有该账户能发行该系列的藏品或封存该系列。
212	func (r *Registry) CreateSeries(id, creatorID, metadata string) error {
213		r.mu.Lock()
214		defer r.mu.Unlock()
215		if err := r.checkOpen(); err != nil {
216			return err
217		}
218		if strings.TrimSpace(id) == "" {
219			return fmt.Errorf("%w: 系列编号不能为空", ErrInvalidArgument)
220		}
221		creator, ok := r.state.Accounts[creatorID]
222		if !ok {
223			return fmt.Errorf("%w: 创建账户 %s", ErrNotFound, creatorID)
224		}
225		if !creator.Active {
226			return fmt.Errorf("%w: 创建账户 %s", ErrAccountInactive, creatorID)
227		}
228		if _, ok := r.state.Series[id]; ok {
229			return fmt.Errorf("%w: 系列 %s", ErrAlreadyExists, id)
230		}
231		r.state.Series[id] = series{ID: id, CreatorID: creatorID, Metadata: metadata}
232		return r.commit()
233	}
234	
235	// SealSeries 封存系列。只有系列创建账户可以封存；封存后不能继续发行，
236	// 已发行藏品仍可转让，且封存不能撤销。
237	func (r *Registry) SealSeries(seriesID, operator string) error {
238		r.mu.Lock()
239		defer r.mu.Unlock()
240		if err := r.checkOpen(); err != nil {
241			return err
242		}
243		s, ok := r.state.Series[seriesID]
244		if !ok {
245			return fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
246		}
247		if s.CreatorID != operator {
248			return fmt.Errorf("%w: 只有创建账户 %s 可以封存系列 %s", ErrForbidden, s.CreatorID, seriesID)
249		}
250		if s.Sealed {
251			return nil // 封存不可撤销，重复封存视为已处于封存态
252		}
253		s.Sealed = true
254		r.state.Series[seriesID] = s
255		return r.commit()
256	}
257	
258	// GetSeries 查询系列；不存在时返回包裹 ErrNotFound 的错误。
259	func (r *Registry) GetSeries(id string) (Series, error) {
260		r.mu.Lock()
261		defer r.mu.Unlock()
262		if err := r.checkOpen(); err != nil {
263			return Series{}, err
264		}
265		s, ok := r.state.Series[id]
266		if !ok {
267			return Series{}, fmt.Errorf("%w: 系列 %s", ErrNotFound, id)
268		}
269		return Series{ID: s.ID, CreatorID: s.CreatorID, Metadata: s.Metadata, Sealed: s.Sealed}, nil
270	}
271	
272	// ---- 发行 ----
273	
274	func (req IssueRequest) validatePresent() error {
275		missing := []string{}
276		if strings.TrimSpace(req.Operator) == "" {
277			missing = append(missing, "operator")
278		}
279		if strings.TrimSpace(req.Reason) == "" {
280			missing = append(missing, "reason")
281		}
282		if strings.TrimSpace(req.RequestID) == "" {
283			missing = append(missing, "request_id")
284		}
285		if strings.TrimSpace(req.ItemID) == "" {
286			missing = append(missing, "item_id")
287		}
288		if strings.TrimSpace(req.SeriesID) == "" {
289			missing = append(missing, "series_id")
290		}
291		if strings.TrimSpace(req.BatchNo) == "" {
292			missing = append(missing, "batch_no")
293		}
294		if strings.TrimSpace(req.HolderID) == "" {
295			missing = append(missing, "holder_id")
296		}
297		if len(missing) > 0 {
298			return fmt.Errorf("%w: 发行请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
299		}
300		return nil
301	}
302	
303	func issueParamsSig(req IssueRequest) string {
304		b, _ := json.Marshal(struct {
305			Kind     string `json:"kind"`
306			ItemID   string `json:"item_id"`
307			SeriesID string `json:"series_id"`
308			BatchNo  string `json:"batch_no"`
309			Metadata string `json:"metadata"`
310			HolderID string `json:"holder_id"`
311			Reason   string `json:"reason"`
312		}{"issue", req.ItemID, req.SeriesID, req.BatchNo, req.Metadata, req.HolderID, req.Reason})
313		return string(b)
314	}
315	
316	// Issue 发行一件藏品。成功后持有版本为 1，初始持有人为 req.HolderID。
317	// 操作者必须是系列创建账户且可用，初始持有人必须已登记且可用，系列未
318	// 封存，藏品编号从未使用过。同一 (操作者, 请求号) 且业务参数相同的
319	// 重复提交返回首次结果；参数不同返回 ErrRequestConflict。
320	//
321	// 状态类拒绝的落盘失败时，与整批发行一致：返回保存错误（保留实际写入
322	// 错误）而非该业务错误，结果为空（无藏品编号、无持有人、无版本、无历史
323	// 序号、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；保存
324	// 条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝条件仍
325	// 在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则正常发行。
326	func (r *Registry) Issue(req IssueRequest) (IssueResult, error) {
327		if err := req.validatePresent(); err != nil {
328			return IssueResult{}, err
329		}
330		r.mu.Lock()
331		defer r.mu.Unlock()
332		if err := r.checkOpen(); err != nil {
333			return IssueResult{}, err
334		}
335	
336		key := requestKey(req.Operator, req.RequestID)
337		sig := issueParamsSig(req)
338		if prev, ok := r.state.Requests[key]; ok {
339			return r.replayIssue(prev, sig)
340		}
341	
342		bizErr := r.checkIssue(req)
343		if bizErr != nil {
344			if !isValidationErr(bizErr) {
345				// 状态类业务拒绝（封存、停用、无权、编号已用等）占用请求号并
346				// 落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
347				r.state.Requests[key] = request{
348					Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
349					Params: sig, Rejected: true, Reason: errCode(bizErr),
350					ItemID: req.ItemID,
351				}
352				if err := r.commit(); err != nil {
353					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批发行一致——
354					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
355					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
356					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
357					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
358					// 的情形。整体返回空结果：无藏品编号、无持有人、无版本、
359					// 无历史序号、不标回放、结果中业务错误为空，error 保留
360					// 实际写入错误。
361					delete(r.state.Requests, key)
362					return IssueResult{}, err
363				}
364			}
365			// 校验类错误（引用不存在等）不占用请求号，也不改变任何状态。
366			return IssueResult{ItemID: req.ItemID, Err: bizErr}, bizErr
367		}
368	
369		seq := r.state.NextSeq + 1
370		r.state.NextSeq = seq
371		r.state.Items[req.ItemID] = item{
372			ID: req.ItemID, SeriesID: req.SeriesID, BatchNo: req.BatchNo,
373			Metadata: req.Metadata, IssuedTxID: seq,
374		}
375		r.state.Holdings[req.ItemID] = holding{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1}
376		r.state.History = append(r.state.History, historyEntry{
377			Seq: seq, Kind: "issue", ItemID: req.ItemID, Operator: req.Operator,
378			Reason: req.Reason, RequestID: req.RequestID,
379			FromID: "", ToID: req.HolderID, FromVersion: 0, ToVersion: 1,
380		})
381		r.state.Requests[key] = request{
382			Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
383			Params: sig, ItemID: req.ItemID, ToID: req.HolderID, Version: 1, TxSeq: seq,
384		}
385		if err := r.commit(); err != nil {
386			return IssueResult{}, err
387		}
388		return IssueResult{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1, TxSeq: seq}, nil
389	}
390	
391	// checkIssue 按单件发行的优先级执行与整批共用的发行资格规则：参数合法
392	// 后，操作者的登记/停用问题优先于系列问题，系列问题内部依次为不存在、
393	// 已封存、操作者不是创建账户，藏品编号已占用又优先于初始持有人问题。
394	func (r *Registry) checkIssue(req IssueRequest) error {
395		return r.checkSingleIssueEligibility(req.Operator, req.SeriesID, req.ItemID, req.HolderID)
396	}
397	
398	func (r *Registry) replayIssue(prev request, sig string) (IssueResult, error) {
399		if prev.Kind != "issue" || prev.Params != sig {
400			return IssueResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
401				ErrRequestConflict, prev.Operator, prev.RequestID)
402		}
403		res := IssueResult{ItemID: prev.ItemID, OwnerID: prev.ToID, Version: prev.Version,
404			TxSeq: prev.TxSeq, Replayed: true}
405		if prev.Rejected {
406			res.Err = codeErr(prev.Reason)
407			return res, res.Err
408		}
409		return res, nil
410	}
411	
412	// ---- 转让 ----
413	
414	func (req TransferRequest) validatePresent() error {
415		missing := []string{}
416		if strings.TrimSpace(req.Operator) == "" {
417			missing = append(missing, "operator")
418		}
419		if strings.TrimSpace(req.Reason) == "" {
420			missing = append(missing, "reason")
421		}
422		if strings.TrimSpace(req.RequestID) == "" {
423			missing = append(missing, "request_id")
424		}
425		if strings.TrimSpace(req.ItemID) == "" {
426			missing = append(missing, "item_id")
427		}
428		if strings.TrimSpace(req.ExpectedOwner) == "" {
429			missing = append(missing, "expected_owner")
430		}
431		if strings.TrimSpace(req.ToID) == "" {
432			missing = append(missing, "to_id")
433		}
434		if req.ExpectedVer <= 0 {
435			missing = append(missing, "expected_version")
436		}
437		if len(missing) > 0 {
438			return fmt.Errorf("%w: 转让请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
439		}
440		if req.Price < 0 {
441			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
442		}
443		return nil
444	}
445	
446	func transferParamsSig(req TransferRequest) string {
447		// Price 用 omitempty：价款为 0 时签名与引入价款前的旧格式一致，
448		// 旧登记册中落盘的请求仍可按原参数回放；改价则签名不同、按请求号
449		// 冲突拒绝。
450		b, _ := json.Marshal(struct {
451			Kind          string `json:"kind"`
452			ItemID        string `json:"item_id"`
453			ExpectedOwner string `json:"expected_owner"`
454			ExpectedVer   int64  `json:"expected_version"`
455			ToID          string `json:"to_id"`
456			Price         int64  `json:"price,omitempty"`
457			Reason        string `json:"reason"`
458		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Price, req.Reason})
459		return string(b)
460	}
