895	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销
896	// （非授权人返回 ErrForbidden）；已使用的授权不能撤销
897	// （ErrAuthorizationUsed）。授权已撤销时再次撤销不新增授权变更记录，按
898	// 成功返回。到期但未使用的授权仍可撤销（变更记录从 expired 记为
899	// revoked）。请求号语义与其他操作一致。
900	//
901	// 无权（ErrForbidden）与已使用（ErrAuthorizationUsed）两类业务拒绝同样
902	// 需要落盘：拒绝结果尚未写入原登记册而保存失败（如数据位置暂时无法写入）
903	// 时，返回实际保存错误，不能只返回上述业务错误让调用者误以为拒绝结果已经
904	// 记住；结果为空（无授权编号、无状态、业务错误为空、不标回放），error 保留
905	// 保存失败的原因。这次未保存的拒绝不改变授权内容、授权变更记录、藏品当前
906	// 持有人和版本，也不占用操作者的本次请求号——即使保存失败后原登记册数据
907	// 暂时无法读取、状态未能按磁盘重建，未保存的拒绝也不能留在当前已打开的
908	// 登记册中，或随之后另一次正常操作被保存下来。保存条件恢复后用同一操作者、
909	// 请求号、授权编号和原因重新提交，按当时的授权情况重新处理：拒绝条件仍存在
910	// 时先成功保存此次拒绝再返回相应业务错误（首次重提不标回放），此后完全相同
911	// 的提交才回放它；失败保存的请求不适用请求号冲突规则，该操作者用同号撤销另
912	// 一份自己有权撤销的授权时不会遭遇请求号冲突。必填内容缺失及授权不存在仍
913	// 直接按原错误拒绝、不占用请求号，不因当前无法保存而变成保存错误。
914	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
915		missing := []string{}
916		if strings.TrimSpace(req.Operator) == "" {
917			missing = append(missing, "operator")
918		}
919		if strings.TrimSpace(req.Reason) == "" {
920			missing = append(missing, "reason")
921		}
922		if strings.TrimSpace(req.RequestID) == "" {
923			missing = append(missing, "request_id")
924		}
925		if strings.TrimSpace(req.AuthID) == "" {
926			missing = append(missing, "auth_id")
927		}
928		if len(missing) > 0 {
929			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
930				ErrInvalidArgument, strings.Join(missing, ", "))
931		}
932		r.mu.Lock()
933		defer r.mu.Unlock()
934		if err := r.checkOpen(); err != nil {
935			return RevokeAuthorizationResult{}, err
936		}
937	
938		now := r.now()
939		key := requestKey(req.Operator, req.RequestID)
940		sig := revokeAuthzParamsSig(req)
941		if prev, ok := r.state.Requests[key]; ok {
942			return r.replayRevokeAuthz(prev, sig)
943		}
944	
945		a, ok := r.state.Authzs[req.AuthID]
946		if !ok {
947			// 引用不存在不占用请求号。
948			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
949			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
950		}
951		if a.GranterID != req.Operator {
952			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
953				ErrForbidden, a.GranterID, req.AuthID)
954			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
955				return RevokeAuthorizationResult{}, err
956			}
957			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
958		}
959		switch authzCurrentStatus(a, now) {
960		case AuthUsed:
961			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
962			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
963				return RevokeAuthorizationResult{}, err
964			}
965			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
966		case AuthRevoked:
967			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
968			// 相同请求重放回放同一结果。
969			r.state.Requests[key] = request{
970				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
971				Params: sig, AuthID: req.AuthID,
972			}
973			if err := r.commit(); err != nil {
974				return RevokeAuthorizationResult{}, err
975			}
976			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
977		}
978	
979		from := AuthActive
980		if authzCurrentStatus(a, now) == AuthExpired {
981			from = AuthExpired
982		}
983		a.Status = "revoked"
984		a.RevokedAt = now
985		r.state.Authzs[req.AuthID] = a
986		authSeq := r.state.NextAuthSeq + 1
987		r.state.NextAuthSeq = authSeq
988		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
989			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
990			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
991			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
992		})
993		r.state.Requests[key] = request{
994			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
995			Params: sig, AuthID: req.AuthID,
996		}
997		if err := r.commit(); err != nil {
998			return RevokeAuthorizationResult{}, err
999		}
1000		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
1001	}
