9	// 本文件为账户停用补充"停用保存失败"场景的回归保障。账户、藏品与持有均
10	// 已存在且可用时，DeactivateAccount 的停用状态尚未原子替换原数据就发生
11	// 写入失败（如数据位置暂时无法写入），这样的失败不是一次有效停用：必须
12	// 返回本次实际的保存错误，不能返回成功，也不能用失败后重新读取原数据时的
13	// 错误取代它。即使原数据仍在、却暂时无法读取或解析、状态未能按磁盘重建，
14	// 同一个仍打开的登记册也必须保持停用前的样子——账户仍可用、编号与元数据
15	// 不变，其已有藏品的持有人、版本与历史原样保留；其他账户此前已经成功停用
16	// 的状态不被恢复为可用。原数据仍可读取的普通保存失败同样撤销本次变化，不
17	// 依赖重新读取成功。随后另一次无关操作成功保存也不会夹带这次未保存的停用；
18	// 读写恢复后该账户仍按原有规则参与转让；之后再次提交停用须重新保存，成功
19	// 返回后才显示不可用，并按现有规则拒绝其发起或接收新的转让。
20	//
21	// 失败注入与其他场景共用：在 .registry.json.tmp 上预建目录，save 在
22	// OpenFile 阶段即以 EISDIR 失败（rename 之前）；部分用例同时把数据文件
23	// 改写为无法解析的内容，覆盖"原数据暂时无法读取、commit 无法按磁盘重建
24	// 状态"。
25	
26	// seedDeactivateWorld 建立停用保存失败用例的初始世界：
27	//   - alice（创作者，元数据"元-alice"）、bob、carol 三个已登记账户；
28	//   - alice 创建系列 s1，发行 i1 给自己后转让给 bob：i1 现为 bob 版本 2；
29	//   - alice 另发行 i2 给自己：alice 仍持有 i2 版本 1，用于核对停用失败
30	//     不改变其名下藏品的持有人、版本与历史；
31	//   - carol 在失败注入前已成功停用，用于核对回滚不会把其他账户的停用
32	//     恢复为可用。
33	func seedDeactivateWorld(t *testing.T, r *Registry) {
34		t.Helper()
35		if err := r.RegisterAccount("alice", "元-alice"); err != nil {
36			t.Fatal(err)
37		}
38		if err := r.RegisterAccount("bob", "元-bob"); err != nil {
39			t.Fatal(err)
40		}
41		if err := r.RegisterAccount("carol", "元-carol"); err != nil {
42			t.Fatal(err)
43		}
44		if err := r.CreateSeries("s1", "alice", "系列"); err != nil {
45			t.Fatal(err)
46		}
47		if _, err := r.Issue(IssueRequest{
48			Operator: "alice", Reason: "首发 i1", RequestID: "ri-i1",
49			ItemID: "i1", SeriesID: "s1", BatchNo: "b1", HolderID: "alice",
50		}); err != nil {
51			t.Fatal(err)
52		}
53		if _, err := r.Transfer(TransferRequest{
54			Operator: "alice", Reason: "转让给 bob", RequestID: "rt-i1-bob", ItemID: "i1",
55			ExpectedOwner: "alice", ExpectedVer: 1, ToID: "bob",
56		}); err != nil {
57			t.Fatal(err)
58		}
59		if _, err := r.Issue(IssueRequest{
60			Operator: "alice", Reason: "首发 i2", RequestID: "ri-i2",
61			ItemID: "i2", SeriesID: "s1", BatchNo: "b1", HolderID: "alice",
62		}); err != nil {
63			t.Fatal(err)
64		}
65		if err := r.DeactivateAccount("carol"); err != nil {
66			t.Fatal(err)
67		}
68	}
69	
70	// assertDeactivateDidNotTakeEffect 在（停用保存失败后的）同一个已打开登记册
71	// 上核对：这次停用如同从未提交，且失败前已有的记录完整保留。
72	func assertDeactivateDidNotTakeEffect(t *testing.T, r *Registry) {
