81		}
82		// 无关的可用账户不受影响。
83		if b, err := r.GetAccount("bob"); err != nil || !b.Active {
84			t.Fatalf("bob 应保持可用: %+v, err %v", b, err)
85		}
86		// 其他账户此前已经成功停用的状态不能被这次回滚恢复为可用。
87		if c, err := r.GetAccount("carol"); err != nil || c.Active {
88			t.Fatalf("carol 应保持已停用: %+v, err %v", c, err)
89		}
90	
91		// 目标账户名下藏品的持有人、版本与历史保留；其曾转出的藏品同样未变。
92		h2, err := r.GetHolding("i2")
93		if err != nil || h2.OwnerID != "alice" || h2.Version != 1 {
94			t.Fatalf("alice 名下 i2 持有被改变: %+v, err %v", h2, err)
95		}
96		h1, err := r.GetHolding("i1")
97		if err != nil || h1.OwnerID != "bob" || h1.Version != 2 {
98			t.Fatalf("i1 持有被失败的停用波及: %+v, err %v", h1, err)
99		}
100		if hs, err := r.HoldingsOf("alice"); err != nil || len(hs) != 1 ||
101			hs[0].ItemID != "i2" || hs[0].Version != 1 {
102			t.Fatalf("alice 持有清单异常: %+v, err %v", hs, err)
103		}
104		if hist, err := r.History("i2"); err != nil || len(hist) != 1 ||
105			hist[0].Kind != "issue" || hist[0].ToID != "alice" {
106			t.Fatalf("i2 历史被改变: %+v, err %v", hist, err)
107		}
108		if hist, err := r.History("i1"); err != nil || len(hist) != 2 ||
109			hist[1].Kind != "transfer" || hist[1].ToID != "bob" {
110			t.Fatalf("i1 历史被改变: %+v, err %v", hist, err)
111		}
112	}
113	
114	// TestDeactivateSaveFailureUnreadableSameRegistry 覆盖核心场景：停用在写入
115	// 阶段失败，且原数据同时被改写为无法解析（commit 无法按磁盘重建状态）。
116	// 返回保存错误而非成功；同一登记册上停用从未生效，旧记录完整。保存仍失败
117	// 时再次停用依旧报保存错误（不能因内存里的幻影停用直接返回成功）。读写
118	// 恢复后先做一次无关操作成功保存，不夹带未保存的停用；账户随后按原规则
119	// 正常发起与接收转让；再次停用重新保存成功后才显示不可用，并拒绝其参与
120	// 新转让，名下藏品与历史仍可查询。
121	func TestDeactivateSaveFailureUnreadableSameRegistry(t *testing.T) {
122		r := mustCreate(t, tempDir(t))
123		seedDeactivateWorld(t, r)
124	
125		orig, err := os.ReadFile(dataFile(r.dir))
126		if err != nil {
127			t.Fatal(err)
128		}
129		blockBatchSave(t, r)
130		if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
131			t.Fatal(err)
132		}
133	
134		// 停用落盘失败：返回实际保存错误，不能是任何业务拒绝，也不能成功。
135		err = r.DeactivateAccount("alice")
136		assertSaveFailureError(t, err)
137		assertDeactivateDidNotTakeEffect(t, r)
138	
139		// 保存条件未恢复时再次提交：仍须报保存错误。修复前内存中已是停用态，
140		// 这里会被幂等分支直接返回成功——必须保持失败。
141		err = r.DeactivateAccount("alice")
142		assertSaveFailureError(t, err)
143		assertDeactivateDidNotTakeEffect(t, r)
144	
145		// 恢复正常读写；先让一次无关操作成功保存，不能夹带这笔未保存的停用。
146		if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
147			t.Fatal(err)
148		}
149		restoreBatchSave(t, r)
150		if err := r.RegisterAccount("eve", "路人"); err != nil {
151			t.Fatalf("无关操作应能成功保存: %v", err)
152		}
153		assertDeactivateDidNotTakeEffect(t, r)
154	
155		// 读写恢复后账户仍按原有规则参与转让：先由 bob 把 i1 转给 alice
156		// （接收人 alice 条件齐备），再由 alice 转回 bob——两笔都正常完成，
157		// 不能因刚才失败的停用收到 ErrAccountInactive。转回后 i1 为 bob
158		// 版本 4，供停用后验证"向停用账户转让被拒绝"。
159		if _, err := r.Transfer(TransferRequest{
160			Operator: "bob", Reason: "恢复后转入 alice", RequestID: "rt-i1-alice",
161			ItemID: "i1", ExpectedOwner: "bob", ExpectedVer: 2, ToID: "alice",
162		}); err != nil {
163			t.Fatalf("账户应仍可接收转让: %v", err)
164		}
165		if _, err := r.Transfer(TransferRequest{
166			Operator: "alice", Reason: "alice 再转回 bob", RequestID: "rt-i1-back",
167			ItemID: "i1", ExpectedOwner: "alice", ExpectedVer: 3, ToID: "bob",
168		}); err != nil {
169			t.Fatalf("账户应仍可发起转让: %v", err)
170		}
171		if h, _ := r.GetHolding("i1"); h.OwnerID != "bob" || h.Version != 4 {
172			t.Fatalf("恢复后转让结果异常: %+v", h)
173		}
174	
175		// 之后再次提交停用：重新完成保存，成功返回后才显示不可用。
176		if err := r.DeactivateAccount("alice"); err != nil {
177			t.Fatalf("恢复后停用应成功保存: %v", err)
178		}
179		if a, _ := r.GetAccount("alice"); a.Active {
180			t.Fatalf("停用保存成功后 alice 应不可用: %+v", a)
181		}
182	
183		// 停用账户按现有规则被拒绝发起新的转让（i2 仍在 alice 手中，版本 1）。
184		if _, err := r.Transfer(TransferRequest{
185			Operator: "alice", Reason: "停用后转出", RequestID: "rt-blocked-out",
186			ItemID: "i2", ExpectedOwner: "alice", ExpectedVer: 1, ToID: "bob",
187		}); !errors.Is(err, ErrAccountInactive) {
188			t.Fatalf("停用账户发起转让应被 ErrAccountInactive 拒绝: %v", err)
189		}
190		// 停用账户按现有规则被拒绝接收新的转让（bob 持 i1 版本 4）。
191		if _, err := r.Transfer(TransferRequest{
192			Operator: "bob", Reason: "停用后转入", RequestID: "rt-blocked-in",
193			ItemID: "i1", ExpectedOwner: "bob", ExpectedVer: 4, ToID: "alice",
194		}); !errors.Is(err, ErrAccountInactive) {
195			t.Fatalf("停用账户接收转让应被 ErrAccountInactive 拒绝: %v", err)
196		}
197		// 停用的创建账户不能再发行。
198		if _, err := r.Issue(IssueRequest{
199			Operator: "alice", Reason: "停用后发行", RequestID: "ri-blocked",
200			ItemID: "i3", SeriesID: "s1", BatchNo: "b1", HolderID: "bob",
201		}); !errors.Is(err, ErrAccountInactive) {
202			t.Fatalf("停用账户发行应被 ErrAccountInactive 拒绝: %v", err)
203		}
204	
205		// 停用本身不改变藏品归属与持有版本，不删除其原有藏品与历史，查询仍可用。
206		if h, _ := r.GetHolding("i2"); h.OwnerID != "alice" || h.Version != 1 {
207			t.Fatalf("停用不应改变 i2 持有: %+v", h)
208		}
209		if h, _ := r.GetHolding("i1"); h.OwnerID != "bob" || h.Version != 4 {
210			t.Fatalf("被拒绝的转让不应改变 i1 持有: %+v", h)
211		}
212		if hs, err := r.HoldingsOf("alice"); err != nil || len(hs) != 1 ||
213			hs[0].ItemID != "i2" {
214			t.Fatalf("停用后名下藏品仍应可查询: %+v, err %v", hs, err)
215		}
216		if hist, err := r.History("i1"); err != nil || len(hist) != 4 {
217			t.Fatalf("停用后历史仍应可查询且不增减: %+v, err %v", hist, err)
218		}
219	
220		// 落盘视角：关闭重开后停用已持久化，其他账户状态与持有一致。
221		dir := r.dir
222		if err := r.Close(); err != nil {
223			t.Fatal(err)
224		}
225		r2, err := Open(dir)
226		if err != nil {
227			t.Fatal(err)
228		}
229		t.Cleanup(func() { _ = r2.Close() })
230		if a, _ := r2.GetAccount("alice"); a.Active || a.Metadata != "元-alice" {
231			t.Fatalf("重开后 alice 应保持停用且元数据不变: %+v", a)
232		}
233		if c, _ := r2.GetAccount("carol"); c.Active {
234			t.Fatalf("重开后 carol 应仍停用: %+v", c)
235		}
236		if e, _ := r2.GetAccount("eve"); !e.Active {
237			t.Fatalf("重开后无关新账户应存在且可用: %+v", e)
238		}
239		if h, _ := r2.GetHolding("i1"); h.OwnerID != "bob" || h.Version != 4 {
240			t.Fatalf("重开后 i1 持有异常: %+v", h)
241		}
242		if h, _ := r2.GetHolding("i2"); h.OwnerID != "alice" || h.Version != 1 {
243			t.Fatalf("重开后 i2 持有异常: %+v", h)
244		}
245	}
246	
247	// TestDeactivateSaveFailureReadableSameRegistry 覆盖：写入失败但原数据仍可
248	// 正常读取（commit 据磁盘内容重建状态）时，得到相同的保障——同一登记册上
249	// 停用从未发生；恢复后重新停用须完整保存一次才生效。
250	func TestDeactivateSaveFailureReadableSameRegistry(t *testing.T) {
251		r := mustCreate(t, tempDir(t))
252		seedDeactivateWorld(t, r)
253	
254		// 只阻断写入，不破坏数据文件：rename 之前失败，原快照完好可读。
255		blockBatchSave(t, r)
256		err := r.DeactivateAccount("alice")
257		assertSaveFailureError(t, err)
258		assertDeactivateDidNotTakeEffect(t, r)
259	
260		restoreBatchSave(t, r)
261		if err := r.DeactivateAccount("alice"); err != nil {
262			t.Fatalf("恢复后重新停用应成功保存: %v", err)
263		}
264		if a, _ := r.GetAccount("alice"); a.Active {
265			t.Fatalf("重新停用保存成功后 alice 应不可用: %+v", a)
266		}
267		// 再次停用已停用账户仍直接成功，且不再写入（否则会被失败注入拦住）。
268		blockBatchSave(t, r)
269		if err := r.DeactivateAccount("alice"); err != nil {
270			t.Fatalf("已停用账户重复停用应直接成功、不要求写入: %v", err)
271		}
272	}
273	
274	// TestDeactivateSaveFailureRetryAfterReopen 覆盖磁盘视角：停用保存失败
275	// （原数据可读）后关闭重开，看到的仍是停用前状态；恢复保存后重新停用
276	// 正常落盘，而不是把一次从未保存的停用当成既成事实。
277	func TestDeactivateSaveFailureRetryAfterReopen(t *testing.T) {
278		dir := tempDir(t)
279		r := mustCreate(t, dir)
280		seedDeactivateWorld(t, r)
281	
282		blockBatchSave(t, r)
283		err := r.DeactivateAccount("alice")
284		assertSaveFailureError(t, err)
285		if err := r.Close(); err != nil {
286			t.Fatal(err)
287		}
288		r2, err := Open(dir)
289		if err != nil {
290			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
291		}
292		t.Cleanup(func() { _ = r2.Close() })
293		assertDeactivateDidNotTakeEffect(t, r2)
294	
295		restoreBatchSave(t, r2)
296		if err := r2.DeactivateAccount("alice"); err != nil {
297			t.Fatalf("重开后重新停用应成功: %v", err)
298		}
299		if a, _ := r2.GetAccount("alice"); a.Active {
300			t.Fatalf("重开后停用保存成功才应不可用: %+v", a)
301		}
302		// 停用账户接收转让按现有规则被拒绝。
303		if _, err := r2.Transfer(TransferRequest{
304			Operator: "bob", Reason: "向停用账户转让", RequestID: "rt-to-inactive",
305			ItemID: "i1", ExpectedOwner: "bob", ExpectedVer: 2, ToID: "alice",
306		}); !errors.Is(err, ErrAccountInactive) {
307			t.Fatalf("向停用账户转让应被 ErrAccountInactive 拒绝: %v", err)
308		}
309		if h, _ := r2.GetHolding("i1"); h.OwnerID != "bob" || h.Version != 2 {
310			t.Fatalf("被拒绝的转让不应改变持有: %+v", h)
311		}
312	}
313	
314	// TestDeactivateUnknownAndIdempotent 保留现有停用入口与错误判定：未登记
315	// 账户返回可由 errors.Is 判断的 ErrNotFound（即使当前正无法写入，也不变成
316	// 保存错误）；已成功停用的账户再次提交直接成功、保持停用，不要求再次写入。
317	func TestDeactivateUnknownAndIdempotent(t *testing.T) {
318		r := mustCreate(t, tempDir(t))
319		seedDeactivateWorld(t, r)
320	
321		if err := r.DeactivateAccount("ghost"); !errors.Is(err, ErrNotFound) {
322			t.Fatalf("未登记账户停用应返回 ErrNotFound: %v", err)
323		}
324		// 写入被阻断时引用检查仍先于保存发生，判定方式不变。
325		blockBatchSave(t, r)
326		if err := r.DeactivateAccount("ghost"); !errors.Is(err, ErrNotFound) {
327			t.Fatalf("写入受限时未登记账户仍应返回 ErrNotFound: %v", err)
328		}
329		// 已停用账户重复停用直接成功，不触发写入（否则会被失败注入拦住）。
330		if err := r.DeactivateAccount("carol"); err != nil {
331			t.Fatalf("已停用账户再次停用应直接成功且不写入: %v", err)
332		}
333		if c, _ := r.GetAccount("carol"); c.Active {
334			t.Fatalf("carol 应保持停用: %+v", c)
335		}
336		// 写入受限时可用账户的停用仍须真实保存并返回保存错误。
337		err := r.DeactivateAccount("bob")
338		assertSaveFailureError(t, err)
339		if b, _ := r.GetAccount("bob"); !b.Active {
340			t.Fatalf("保存失败后 bob 应仍可用: %+v", b)
341		}
342	}
343

