		t.Fatalf("写入受限时非创建账户仍应返回 ErrForbidden: %v", err)
	}
	// 已封存系列重复封存直接成功，不触发写入（否则会被失败注入拦住）。
	if err := r.SealSeries("s2", "alice"); err != nil {
